/**
 * MorphoNews Layout: 自律的パルス・マトリックス
 * Generation: #70
 * Mood: Autonomous (Systemic Organicism)
 */

:root {
    --layout-max-width: 1400px;
    --layout-news-columns: repeat(auto-fill, minmax(380px, 1fr));
    --layout-card-gap: 5rem 2.5rem;
    --layout-card-direction: row;
    --layout-animation-style: autonomous-reveal;
    --pulse-speed: 3s;
}

#news-container {
    display: grid;
    grid-template-columns: var(--layout-news-columns);
    gap: var(--layout-card-gap);
    max-width: var(--layout-max-width);
    margin: 6rem auto;
    padding: 0 2.5rem;
    align-items: start;
}

.news-card {
    display: grid;
    grid-template-rows: auto auto 1fr auto;
    grid-row: span 1;
    gap: 1.5rem;
    background: transparent;
    position: relative;
    padding: 2rem;
    border-left: 1px solid rgba(var(--morpho-accent-primary-rgb), 0.3);
    transition: border-color 0.4s ease, transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);

    /* Scroll-driven Animation Setup */
    view-timeline-name: --card-scroll;
    animation: var(--layout-animation-style) both linear;
    animation-timeline: --card-scroll;
    animation-range: entry 10% cover 40%;
}

@keyframes autonomous-reveal {
    from {
        opacity: 0;
        clip-path: inset(100% 0 0 0);
        transform: translateY(50px) scale(0.98);
        filter: brightness(2) contrast(0.5);
    }
    to {
        opacity: 1;
        clip-path: inset(0 0 0 0);
        transform: translateY(0) scale(1);
        filter: brightness(1) contrast(1);
    }
}

